"Small-cap stocks showing extreme volume spikes are likely to underperform in the following days due to overreaction and subsequent mean reversion.",
  "factors": [
    {
      "name": "vol_reversal_rank",
      "expression": "RANK(TS_ZSCORE(TS_ARGMAX($volume, 5), 20))",
      "explanation": "Measures the rank of the highest volume day within a 20-day window, scaled by volatility to capture overreaction and subsequent mean reversion."
    },
    {
      "name": "vol_skew_diff",
      "expression": "TS_PCTCHANGE(TS_SKEW($return, 5), TS_SKEW($volume, 5), 1)",
      "explanation": "Compares the skewness of returns and volume over a 5-day window, capturing asymmetry in price and trading behavior that may signal overreaction."
    },
    {
      "name": "residual_volume",
      "expression": "REGRESI($close, $volume, 5) * TS_MAD($volume, 5)",
      "explanation": "Uses the residual from regressing close prices on volume, scaled by volume dispersion, to highlight deviations from expected price-volume relationships."
    },
    {
      "name": "quantile_gap",
      "expression": "(TS_QUANTILE($volume, 5, 0.9) - TS_QUANTILE($volume, 5, 0.1)) / TS_MAD($volume, 5)",
      "explanation": "Captures the spread between the top and bottom 10% of volume days, normalized by dispersion, to identify extreme volume events that may signal overreaction."
    },
    {
      "name": "vol_asymmetry",
      "expression": "FILTER($return, $volume > TS_MEDIAN($volume, 5)) * TS_ZSCORE($return, 1)",
      "explanation": "Filters returns based on volume exceeding the median, then scales by return volatility, to focus on high-volume-driven movements."
    },
    {
      "name": "vol_corr_diff",
      "expression": "TS_CORR($volume, $open, 5) - TS_CORR($volume, $close, 5)",
      "explanation": "Compares the correlation between volume and open vs. close prices, highlighting shifts in market sentiment that may precede reversals."
    }
  ]
}

